document.addEventListener('click',e=>{const t=e.target.closest('[data-pq]');if(!t||!document.querySelector('#psBar'))return;const a=t.dataset.pq,k=t.dataset.k,bar=document.querySelector('#psBar');if(a==='model'){PQM=!!t.checked;pqRender();return}if(a==='quote'){pqQuote();return}if(a==='enquiry'){e.preventDefault();pqEnquiry();return}if(a==='modelsw'){PQM=!PQM;pqRender();return}if(a==='taxsw'){PQT=!PQT;pqRender();return}
 if(a==='plan-d'||a==='plan-h'){const sh=t.closest('.ps2');sh.classList.toggle('is-home',a==='plan-h');const hm=a==='plan-h';if(hm){if(!window.__pqm0)window.__pqm0={v:PQM};PQM=true}else if(window.__pqm0){PQM=window.__pqm0.v;window.__pqm0=null}window.PQK=hm?2:1;{const pd=sh.querySelector('.ps-plan-d'),ph=sh.querySelector('.ps-plan-h');if(pd&&ph){if(hm)sh.insertBefore(ph,pd);else pd.after(ph)}}pqPrices();pqRender();sh.querySelectorAll('.ps-switch button').forEach(b=>b.setAttribute('aria-pressed',String(b===t)));return}if(a==='tab'){const sh=t.closest('.ps2');sh.querySelectorAll('.ps-chip').forEach(b=>b.setAttribute('aria-pressed',String(b===t)));sh.querySelectorAll('.ps-card').forEach(c=>c.classList.toggle('on',c.id==='ps-'+k));return}if(a==='more'){const c=t.closest('.ps-card'),n=Number(t.dataset.n),col=c.classList.toggle('collapsed');t.setAttribute('aria-expanded',String(!col));t.textContent=col?pick('展開其他 '+n+' 項','Show '+n+' more'):pick('收合','Show less');return}if(a==='r+'){if(PQ[k])PQ[k].qty=Math.min(20,PQ[k].qty+1);else PQ[k]={qty:1,extra:0}}else if(a==='r-'){if(PQ[k]&&PQ[k].qty>1)PQ[k].qty--;else delete PQ[k]}
 else if(a==='e+'&&!PQ[k]){PQ[k]={qty:1,extra:1}}else if(a==='clear'){for(const x of Object.keys(PQ))delete PQ[x];bar.classList.remove('open')}
 else if(a==='toggle'){bar.classList.toggle('open')}
 else if(PQ[k]){const it=PQ[k];if(a==='q+')it.qty=Math.min(20,it.qty+1);if(a==='q-')it.qty=Math.max(1,it.qty-1);if(a==='e+')it.extra=Math.min(40,it.extra+1);if(a==='e-')it.extra=Math.max(0,it.extra-1)}
 pqRender()});
new MutationObserver(()=>{if(document.querySelector('#psBar')&&!document.querySelector('#psBar').firstChild)pqRender()}).observe(document.documentElement,{childList:true,subtree:true});
function homeTable(){const n=v=>v.toLocaleString('en-US');return '<div class="ph-price"><div class="ph-groups">'+PRICE_GROUPS.map(g=>'<article class="ph-group"><h5>'+g.k+' · '+pick(g.zh,g.en)+'</h5><div class="ph-row ph-row-h"><span>'+pick('空間','Space')+'</span><span>'+pick('元／張','NT$ / view')+'</span><span>'+pick('追加視角／張','Extra view')+'</span></div>'+g.rows.map(r=>'<div class="ph-row"><span>'+pick(r[0],r[1])+'</span><b>'+n(r[2]*2)+'</b><em>'+n(r[3]*2)+'</em></div>').join('')+'</article>').join('')+'</div></div>'}
function homeQA(){return '<section class="section"><div class="wrap">'+sectionHead('QUESTIONS',pick('常見問題','Common questions'))+'<div class="faq"><details open><summary>'+pick('為什麼屋主方案比設計師方案貴？','Why is the homeowner plan priced higher?')+'</summary><p><b>'+pick('設計師方案','Designer plan')+'</b>　'+pick('設計已經由設計師完成，我們只負責把它做成圖，所以價格較低。','The design is already done by the designer; we only turn it into images, so the price is lower.')+'</p><p><b>'+pick('屋主方案','Homeowner plan')+'</b>　'+pick('多數屋主心裡有想法、手上有平面圖，但要把設計具體畫出來並不容易。所以我們會先陪你一起討論空間配置、材質、燈光與風格，把想法整理成可以落實的設計，再做成圖。這段需要設計判斷與來回討論，所以費用較高。','Most homeowners have ideas or a floor plan, but turning them into a concrete design is not easy. So we first work through layout, materials, lighting and style with you, shaping your ideas into a design that can be built, then render it. This takes design judgement and back-and-forth, so it costs more.')+'</p></details></div></div></section>'}
function priceHome(){return '<section class="ps-plan-h" aria-label="'+pick('屋主方案','Homeowner plan')+'"><p class="ps-eyebrow">3D ASSISTED INTERIOR DESIGN</p><h4>'+pick('屋主・3D 輔助室內設計','Homeowners · 3D-assisted interior design')+'</h4><p class="ph-lead">'+pick('給想自己的家有好設計、但手上只有想法或平面圖的人。我們協助設計，再用 3D 把結果畫給你看。','For people who want a well-designed home but only have ideas or a floor plan. We help design it, then show you the result in 3D.')+'</p>'+homeTable()+'<a class="button" href="contact.html?topic=interior">'+pick('洽詢屋主方案','Ask about the homeowner plan')+' ↗</a></section>'}function priceSheet(){const n=v=>v.toLocaleString('en-US'),rng=g=>{const a=g.rows.map(r=>r[2]),lo=Math.min(...a),hi=Math.max(...a);return lo===hi?'NT$ '+n(lo):'NT$ '+n(lo)+' – '+n(hi)};
 const chips=PRICE_GROUPS.map(g=>'<button type="button" class="ps-chip" data-pq="tab" data-k="'+g.k+'" aria-pressed="'+(g.k==='01')+'"><span>'+g.k+'</span><b>'+pick(g.zh,g.en)+'</b><em>'+rng(g)+'</em></button>').join('');
 const cards=PRICE_GROUPS.map((g,i)=>'<article class="ps-card'+(i===0?' on':'')+'" id="ps-'+g.k+'"><div class="ps-photo'+(PRICE_PHOTOS[i]?'':' nophoto')+'">'+(PRICE_PHOTOS[i]?'<img src="'+PRICE_PHOTOS[i]+'" alt="" loading="lazy">':'')+'<span class="ps-no">'+g.k+'</span></div><div class="ps-body"><h4>'+pick(g.zh,g.en)+'<small>'+(language==='zh'?g.en:g.zh)+'</small><span class="ps-rng">'+pick('單價 ','Per space ')+rng(g)+'</span></h4><p class="ps-range"><span>'+pick('每個空間','Per space')+'</span><b>'+rng(g)+'</b></p><div class="ps-head"><span>'+pick('空間','Space')+'</span><span>'+pick('元／張','NT$ / view')+'</span><span>'+pick('追加視角／張','Extra view')+'</span><span>'+pick('數量','Qty')+'</span><span>'+pick('建模費','Modelling')+'</span></div><ul>'+g.rows.map((r,j)=>'<li data-k="'+i+'-'+j+'"><span class="ps-name">'+pick(r[0],r[1])+'<small class="ps-model">'+pick('需建模 +','Modelling +')+'NT$ '+n(pqMF(i,j))+'</small></span><b>'+n(r[2])+'</b><span class="ps-mp">'+n(pqMF(i,j))+'</span><em class="ps-ex"><i data-l="'+pick('追加視角 ','Extra view ')+'">'+n(r[3])+'</i><span class="ps-xs" data-k="'+i+'-'+j+'"></span></em><span class="ps-stp" data-k="'+i+'-'+j+'"></span></li>').join('')+'</ul><p class="ps-model-once"><button type="button" class="ps-sw" role="switch" aria-checked="false" data-pq="modelsw"><i></i><span>'+pick('建模費','Modelling')+'</span></button><button type="button" class="ps-sw" role="switch" aria-checked="false" data-pq="taxsw"><i></i><span>'+pick('含稅 5%','Incl. 5% tax')+'</span></button>'+modelTip()+'</p>'+(g.rows.length>3?'<button type="button" class="ps-more" data-pq="more" aria-expanded="false" data-n="'+(g.rows.length-3)+'">'+pick('展開其他 '+(g.rows.length-3)+' 項','Show '+(g.rows.length-3)+' more')+'</button>':'')+'</div></article>');
 const rules=[[pick('不算修改次數','Not counted as revisions'),pick('整體與局部材質調色、色明亮、色相皆不算修改次數。','Overall and local material colour, brightness and hue adjustments do not count as revisions.')],[pick('小改動','Minor change'),pick('局部材質、家具、擺飾改動以及局部硬裝改動為小改動，費用同加張收費。','Local material, furniture, decor and local hard-finish changes are minor changes, charged like an extra view.')],[pick('大改動','Major change'),pick('平面佈局、硬裝大幅調整，此為大改動，加收原價格一半。','Floor-plan or major hard-finish changes are major changes, charged at half of the original price.')],[pick('異形・高難度建模','Complex modelling'),pick('如遇異形建模以及高難度建模，效果需加收費用（雙方另行商議價格）。','Irregular or highly complex modelling is charged extra (price agreed separately).')]];
 return '<div class="interior-pricing price-sheet ps2" id="interior-pricing"><div class="ps-top"><div><p class="ps-eyebrow">2026 PRICE LIST · NT$</p><h3>'+pick('效果圖方案','Rendering plans')+'</h3></div><p class="ps-note">'+pick('金額為新台幣；實際金額依空間與專案確認。','Prices are in NTD; final amounts are confirmed per space and project.')+'</p></div><div class="ps-switch" role="group" aria-label="'+pick('方案對象','Plan for')+'"><button type="button" class="on" data-pq="plan-d" aria-pressed="true">'+pick('室內設計師','Interior designers')+'</button><button type="button" data-pq="plan-h" aria-pressed="false">'+pick('屋主／一般人','Homeowners')+'</button></div><div class="ps-plan-d"><nav class="ps-chips" aria-label="'+pick('空間類別','Space types')+'">'+chips+'</nav><div class="ps-cards"><div class="ps-col">'+[0,1,4].map(i=>cards[i]).join('')+'</div><div class="ps-col">'+[2,3].map(i=>cards[i]).join('')+'</div></div><div class="ps-bar" id="psBar" aria-live="polite"></div><details open class="ps-info" style="margin:14px 0 0;border:1px solid #D9E1E3;border-radius:8px;padding:12px 14px"><summary style="cursor:pointer;color:#51656C">'+pick('報價單資訊（選填，填寫後報價單會自動帶入）','Quotation details (optional; filled into the quotation)')+'</summary><div style="display:flex;flex-wrap:wrap;gap:16px;margin-top:12px"><div style="display:flex;flex-direction:column;gap:8px;flex:1 1 260px"><b style="color:#2B8C88;font-weight:600">'+pick('公司','Company')+'</b><input data-pi="c" style="height:36px;padding:0 10px;border:1px solid #D9E1E3;border-radius:6px;background:#fff;color:#14242A;font:inherit;font-size:14px;min-width:0" placeholder="'+pick('單位／客戶名稱（例：某某室內設計工作室）','Company / client (e.g. Studio Name)')+'" value="'+esc((window.PQI||{})['c']||'')+'"><input data-pi="n" style="height:36px;padding:0 10px;border:1px solid #D9E1E3;border-radius:6px;background:#fff;color:#14242A;font:inherit;font-size:14px;min-width:0" placeholder="'+pick('聯絡人（例：王小姐）','Contact person (e.g. Ms. Wang)')+'" value="'+esc((window.PQI||{})['n']||'')+'"><input data-pi="t" style="height:36px;padding:0 10px;border:1px solid #D9E1E3;border-radius:6px;background:#fff;color:#14242A;font:inherit;font-size:14px;min-width:0" placeholder="'+pick('電話（例：0912-345-678）','Phone (e.g. 0912-345-678)')+'" value="'+esc((window.PQI||{})['t']||'')+'"><input data-pi="e" style="height:36px;padding:0 10px;border:1px solid #D9E1E3;border-radius:6px;background:#fff;color:#14242A;font:inherit;font-size:14px;min-width:0" placeholder="'+pick('Email（填寫後可直接寄出）','Email (fill in to send directly)')+'" value="'+esc((window.PQI||{})['e']||'')+'"></div><div style="display:flex;flex-direction:column;gap:8px;flex:1 1 260px"><b style="color:#2B8C88;font-weight:600">'+pick('專案','Project')+'</b><input data-pi="p" style="height:36px;padding:0 10px;border:1px solid #D9E1E3;border-radius:6px;background:#fff;color:#14242A;font:inherit;font-size:14px;min-width:0" placeholder="'+pick('專案名稱（例：信義區住宅 A 戶）','Project name (e.g. Xinyi Residence)')+'" value="'+esc((window.PQI||{})['p']||'')+'"><input data-pi="a" style="height:36px;padding:0 10px;border:1px solid #D9E1E3;border-radius:6px;background:#fff;color:#14242A;font:inherit;font-size:14px;min-width:0" placeholder="'+pick('專案地址（例：台北市信義區松仁路 100 號）','Address (e.g. 100 Songren Rd, Taipei)')+'" value="'+esc((window.PQI||{})['a']||'')+'"><input data-pi="m" style="height:36px;padding:0 10px;border:1px solid #D9E1E3;border-radius:6px;background:#fff;color:#14242A;font:inherit;font-size:14px;min-width:0" placeholder="'+pick('備註（例：客廳加一個夜景視角）','Notes (e.g. one extra night view for the living room)')+'" value="'+esc((window.PQI||{})['m']||'')+'"></div></div></details><p class="ps-final">'+pick('※ 概估金額；案件有特殊需求時，我方保留重新估價的權利。建模費及本報價之最終解釋權歸我方。','* Estimates only. Where a project has special requirements, we may re-quote. The final interpretation of the modelling fee and of this quotation rests with us.')+'</p><div class="ps-rules"><h4>'+pick('修改原則','Revision policy')+'</h4><ol>'+rules.map((x,i)=>'<li><span>0'+(i+1)+'</span><b>'+x[0]+'</b><p>'+x[1]+'</p></li>').join('')+'</ol></div></div>'+priceHome()+'</div>'}
function interiorPricing(){return '<section class="interior-service" id="interior-visualization" aria-labelledby="interiorServiceTitle"><div class="interior-service-inner"><header class="interior-service-intro"><p class="eyebrow">INTERIOR VISUALIZATION</p><h2 id="interiorServiceTitle">'+pick('室內設計效果圖','Interior Renderings')+'</h2><p>'+pick('協助室內設計師與設計團隊呈現材質、燈光與空間氛圍。圖面素材、製作範圍與交付規格依專案確認。','Renderings for interior designers and design teams, communicating materials, lighting and spatial atmosphere. Drawings, scope and delivery are agreed for each project.')+'</p><div class="actions"><a class="button" href="contact.html?topic=interior">'+pick('洽詢製作需求','Discuss your project')+' ↗</a><a class="button ghost" href="'+routes.interiorworks+'">'+pick('查看室內效果圖作品','View interior work')+' ↗</a></div></header>'+priceSheet()+'</div></section>'}
function interior(){return intro('INTERIOR VISUALIZATION',pick('室內設計效果圖','Interior Renderings'),pick('協助室內設計師與設計團隊呈現材質、燈光與空間氛圍。圖面素材、製作範圍與交付規格依專案確認。','Renderings for interior designers and design teams, communicating materials, lighting and spatial atmosphere. Drawings, scope and delivery are agreed for each project.'),true)+'<section class="wrap interior-page" id="interior-visualization"><div class="interior-service-inner"><div class="actions"><a class="button" href="contact.html?topic=interior">'+pick('洽詢製作需求','Discuss your project')+' ↗</a><a class="button ghost" href="'+routes.interiorworks+'">'+pick('查看室內效果圖作品','View interior work')+' ↗</a></div>'+priceSheet()+'</div></section>'+homeQA()+contactBand()}
function interiorWorks(){return intro('INTERIOR RENDERINGS',pick('室內設計效果圖作品','Interior rendering portfolio'),pick('為室內設計師與設計團隊製作的效果圖作品。','Renderings produced for interior designers and design teams.'),true)+'<section class="wrap interior-works-page">'+interiorPortfolio()+'<div class="actions"><a class="button" href="'+routes.interior+'">'+pick('查看價目與方案','View pricing & plans')+' ↗</a><a class="button ghost" href="contact.html?topic=interior">'+pick('洽詢製作需求','Discuss your project')+' ↗</a></div></section>'+contactBand()}
function services(){const faq=language==='zh'?CONTENT.faq:en.faq;return intro('SERVICES',pick('服務項目','Services'),pick('先檢視目前的做法，再決定需要簡化、串接，還是製作專用工具。','Review the current way of working before deciding what to simplify, connect or build.'),true)+'<section class="wrap service-showcase">'+serviceData().map((v,i)=>'<a href="#service-'+(i+1)+'" class="showcase-card"><span class="index">0'+(i+1)+'</span>'+icon(i)+'<h2>'+(language==='zh'&&i===0?'<span class="service-title-part">重複工作自動化</span><wbr><span class="service-title-part">與流程優化</span>':esc(v.title))+'</h2><span class="card-enter">↗</span></a>').join('')+'<a href="#service-website" class="showcase-card"><span class="index">05</span>'+websiteServiceIcon()+'<h2>'+pick('品牌網站與互動網頁設計','Brand Websites & Interactive Experiences')+'</h2><span class="card-enter">↗</span></a><a href="#service-interior" class="showcase-card"><span class="index">06</span>'+interiorServiceIcon()+'<h2>'+pick('室內設計效果圖','Interior Renderings')+'</h2><span class="card-enter">↗</span></a><a href="#service-music" class="showcase-card"><span class="index">07</span>'+musicServiceIcon()+'<h2>'+pick('數位音樂與 MV 製作','Digital Music & Music Videos')+'</h2><span class="card-enter">↗</span></a></section><section class="wrap page-bottom">'+serviceData().map((v,i)=>'<article class="service-detail" id="service-'+(i+1)+'"><div><span class="index">0'+(i+1)+'</span>'+icon(i)+'</div><div><h2>'+esc(v.title)+'</h2><p>'+esc(v.summary)+'</p></div><ul class="scope-list">'+v.scope.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></article>').join('')+websiteService()+interiorService()+musicService()+'</section><section class="section"><div class="wrap">'+sectionHead('QUESTIONS',pick('先把問題說清楚。','A few things worth clarifying.'))+'<div class="faq">'+faq.map(v=>'<details><summary>'+esc(v.question)+'</summary><p>'+esc(v.answer)+'</p></details>').join('')+'</div></div></section>'+contactBand()}
function interiorServiceIcon(){return '<svg class="service-icon reference-glass" viewBox="0 0 128 128" width="128" height="128" aria-hidden="true" fill="none" stroke="#C9DADD" stroke-width="1.4" stroke-linejoin="round"><defs><linearGradient id="isg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".35"/><stop offset="1" stop-color="#73DBD6" stop-opacity=".08"/></linearGradient></defs><path d="M20 44 64 22l44 22v46L64 112 20 90z" fill="url(#isg)"/><path d="M20 44l44 22 44-22M64 66v46"/><path d="M38 78l16 8M74 92l22-11" opacity=".6"/><circle cx="64" cy="66" r="2.4" fill="#73DBD6" stroke="none"/></svg>'}
function interiorService(){return '<article class="service-detail" id="service-interior"><div><span class="index">06</span>'+interiorServiceIcon()+'</div><div><h2>'+pick('室內設計效果圖','Interior Renderings')+'</h2><p>'+pick('協助室內設計師與設計團隊呈現材質、燈光與空間氛圍。','Renderings for designers and design teams: materials, lighting and atmosphere.')+'</p><div class="actions"><a class="button" href="'+routes.interior+'">'+pick('查看價目與方案','View pricing & plans')+' ↗</a></div></div><ul class="scope-list"><li>'+pick('住宅空間','Residential spaces')+'</li><li>'+pick('商空與餐飲','Commercial and dining')+'</li><li>'+pick('辦公空間','Office spaces')+'</li><li>'+pick('飯店空間','Hotel spaces')+'</li><li>'+pick('建築外觀','Building exteriors')+'</li></ul></article>'}
function scopeTip(){return '<div class="scope-tip"><button class="scope-tip-btn" type="button" aria-describedby="scopeTip"><i aria-hidden="true">i</i>'+pick('範圍說明','Scope notes')+'</button><div class="scope-tip-card" id="scopeTip" role="tooltip">'+pick('範圍依資料格式、環境與授權評估；自動操作、跨系統整合與 AI 串接不保證適用所有情境。','Scope depends on formats, environment and permissions; automation, integration and AI are assessed per workflow.')+'</div></div>'}
function musicService(){return '<article class="service-detail" id="service-music"><div><span class="index">07</span>'+musicServiceIcon()+'</div><div><div class="title-row"><h2>'+pick('數位音樂與 MV 製作','Digital Music & Music Videos')+'</h2>'+scopeTip()+'</div><p>'+pick('品牌與影片配樂、原創歌曲，以及依歌曲規劃的 MV 製作。','Soundtracks, original songs, and music videos paced to the song.')+'</p><div class="actions"><a class="button" href="'+routes.music+'">'+pick('前往音樂與 MV 頁','View music & MV')+' ↗</a></div></div><ul class="scope-list"><li>'+pick('品牌與影片配樂','Soundtracks for brands and video')+'</li><li>'+pick('原創歌曲','Original songs')+'</li><li>'+pick('依歌曲規劃的 MV 製作','Music videos paced to the song')+'</li><li>'+pick('頁面內直接試聽作品','Listen to samples on the page')+'</li></ul></article>'}
function process(){const outputs=language==='zh'?[['現有流程與資料來源','痛點、限制與目標'],['功能與排除範圍','可觀察的驗收條件'],['可操作的核心流程','異常處理與人工確認'],['約定案例的驗收結果','操作、備份與維護說明']]:[['Current workflow and data sources','Pain points, constraints and goals'],['Features and explicit exclusions','Observable acceptance criteria'],['An operable core workflow','Exceptional inputs and human review'],['Results against the agreed examples','Operating, backup and maintenance notes']];return intro('OUR PROCESS',pick('開發流程','Our process'),pick('動畫裡的感應、鏈接與聚合，也是一種工作方法：先理解，再建立關係，最後交付清晰的結果。','The sensing, connection and assembly in our visual identity reflect a way of working: understand first, establish relationships, then deliver a clear result.'),true)+'<section class="wrap process-overview" aria-label="'+pick('四個合作階段','Four stages of collaboration')+'">'+processData().map((v,i)=>'<a href="#step-'+(i+1)+'"><span class="stage-orbit">0'+(i+1)+'</span><strong>'+esc(v.title)+'</strong><small>'+['DISCOVER','VISUALIZE','DEVELOP','DELIVER'][i]+'</small></a>').join('')+'</section><section class="wrap page-bottom journey">'+processData().map((v,i)=>'<article class="journey-step" id="step-'+(i+1)+'"><div class="journey-number">0'+(i+1)+'</div><div><p class="eyebrow">'+['DISCOVER','VISUALIZE','DEVELOP','DELIVER'][i]+'</p><h2>'+esc(v.title)+'</h2><p>'+esc(v.description)+'</p></div><div class="deliverable"><p class="eyebrow">'+pick(['需求摘要','工作範圍','品質檢核','成果清單'][i],['Requirements summary','Scope of work','Quality checks','Deliverables'][i])+'</p><ul>'+outputs[i].map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div></article>').join('')+'</section>'+contactBand()}
function aboutValueIcon(i){const id='about-value-'+(++glassSerial);const shapes=[
'<g transform="scale(.96)"><path d="M43 19 72 68 19 68Z" fill="url(#'+id+'-glass)" stroke="currentColor"/><path d="m43 19 9 28 20 21M19 68l33-21" fill="none" stroke="currentColor" opacity=".7"/><path d="M5 46h34m13 1 39-20M52 47l40 7M52 47l30 33" fill="none" stroke="#73dbd6"/><circle cx="52" cy="47" r="2" fill="#e9ffff"/><path d="m19 77 26 9 34-11" stroke="currentColor" opacity=".3" fill="none"/></g>',
'<path d="M25 28 48 48 74 28M48 48v29" stroke="#73dbd6"/><path d="m13 18 12-7 12 7v15l-12 7-12-7Zm49 0 12-7 12 7v15l-12 7-12-7ZM36 69l12-7 12 7v15l-12 7-12-7Z" fill="url(#'+id+'-glass)"/><path d="m13 18 12 7 12-7m-12 7v15m37-22 12 7 12-7m-12 7v15M36 69l12 7 12-7m-12 7v15"/><circle cx="48" cy="48" r="5" fill="#73dbd6" fill-opacity=".4"/>',
'<g transform="scale(.96)"><path d="m13 61 38-19 37 19-37 21Z" fill="url(#'+id+'-glass)" stroke="currentColor"/><path d="M13 61v10l38 21 37-21V61M51 82v10" fill="none" stroke="currentColor" opacity=".7"/><path d="m36 25 15-8 15 8v20L51 54 36 45Z" fill="url(#'+id+'-glass)" stroke="currentColor"/><path d="m36 25 15 8 15-8M51 33v21" stroke="currentColor" fill="none"/><path d="M36 49v12m30-12v12m-15-3v8" stroke="#73dbd6" stroke-dasharray="2 4" fill="none"/><path d="m36 62 15 8 15-8" stroke="#73dbd6" fill="none"/></g>'
][i];return '<svg class="service-icon about-value-icon" data-value-icon="'+i+'" viewBox="0 0 96 96" fill="none" aria-hidden="true"><defs><linearGradient id="'+id+'-glass" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e9f8fa" stop-opacity=".16"/><stop offset="1" stop-color="#73dbd6" stop-opacity=".03"/></linearGradient></defs><g stroke="#b4d1d6" stroke-width="1" stroke-linecap="round" stroke-linejoin="round">'+shapes+'</g></svg>'}
function about(){const values=language==='zh'?[['設計思考','從人的實際操作與理解方式出發，讓資訊和介面更容易使用。'],['技術整合','先理解資料如何流動，再選擇適合的工具與串接方式。'],['實用價值','用明確範圍、可觀察案例與必要人工確認，檢視成果能否真的用在工作裡。']]:[['Design thinking','Start with how people work and understand information, so interfaces and tools are easier to use.'],['Technical integration','Understand how data moves before choosing the tools and connections that support it.'],['Real-world value','Use a clear scope, observable examples and appropriate human review to assess whether the result works in practice.']];return '<section class="wrap about-lead"><div class="about-lead-copy"><p class="eyebrow">ABOUT FORM³</p><h1>'+pick('關於 FORM³','About FORM³')+'</h1><p class="studio-descriptor">Digital Tools · Creative Studio<br>· Visual Expression</p><h2>'+pick('把想法，轉化為體驗。','Give ideas a useful form.')+'</h2><p>'+pick('建築視覺讓抽象的空間能被看見；軟體與資料工具，則讓複雜的工作可以被理解、整理與重複執行。FORM³ 從實際需求出發，製作清晰而實用的解決方案。','Architectural visualization makes imagined spaces visible. Software and data tools make complex work easier to understand, organize and repeat. FORM³ builds clear, practical solutions around real requirements.')+'</p><p>'+pick('目前以工作流程自動化與客製軟體開發作為主要服務，建築與空間視覺持續作為工作室的專業領域。','Our primary services focus on workflow automation and custom software, while architectural and spatial visualization remain part of the studio’s practice.')+'</p><p class="about-independent">'+pick('本站所有作品，皆為 FORM³ 獨立製作。','Every work shown on this site is independently produced by FORM³.')+'</p></div><div class="about-lead-art">'+referenceArt('about')+'</div></section>'+pick('<section class="section about-founder-sec" id="founder"><div class="wrap about-founder"><div class="about-founder-copy"><p class="eyebrow">FOUNDER</p><h2>劉名烜<span>FORM³ 立方體視覺表現工作室 主理人</span></h2><p>國立雲林科技大學建築與室內設計系畢業，<span class="nb">畢業總評獲最大獎「新銳設計師獎」</span>。從大學起，他就一頭栽進效果圖，把「一張圖如何變成真實的空間」當成一輩子的功課；沒有捷徑，靠一張張練習自學、反覆磨練。從施工圖做起，進入建築與室內設計事務所，在設計與溝通中累積經驗，再轉向專職 3D 效果圖，二十年來始終站在「圖面變成空間」的那條線上。</p><p>2020 年創立立方體視覺表現工作室，從需求溝通、建模、材質光影到最後交付，每一張圖都親自把關。</p><p>多年鑽研工作流，讓他對 AI 自動化如何一步步落地有一套自己的想法：先看清楚流程，再決定哪些交給程式、哪些留給人，讓工具真正幫上手邊的工作。</p><div class="about-skills"><p class="about-skills-label">精通軟體</p><ul><li>3ds Max</li><li>Corona Renderer</li><li>Photoshop</li><li>AutoCAD</li><li>SketchUp</li></ul><p class="about-skills-label about-skills-label2">AI 工具</p><ul><li>Codex</li><li>Claude</li><li>ComfyUI</li></ul></div></div><figure class="about-founder-photo"><img src="assets/founder-20261121-v5.jpg" alt="FORM³ 主理人劉名烜，掌心托著發光的透明立方體" width="940" height="941" loading="lazy" decoding="async"></figure></div></section>','<section class="section about-founder-sec" id="founder"><div class="wrap about-founder"><div class="about-founder-copy"><p class="eyebrow">FOUNDER</p><h2>Ming-Xuan Liu<span>Founder, FORM³ Visualization Studio</span></h2><p>He has been immersed in architectural rendering since university, treating one question as lifelong work: how an image becomes a real space. There were no shortcuts, only years of teaching himself and refining the craft through practice. After graduating from an architecture and interior design programme and winning the New Designer Award, the top prize of his graduation review, he began with construction drawings, moved into architecture and interior design studios, and then into full-time 3D visualization. For 20 years he has worked where drawings turn into spaces.</p><p>Since founding FORM³ in 2020, he has personally overseen every image: from brief and modelling to light, materials and delivery.</p><p>Years of studying how work actually flows have given him a clear point of view on how AI automation should take hold: map the process first, then decide what goes to software and what stays with people, so the tools genuinely help the work at hand.</p><div class="about-skills"><p class="about-skills-label">Proficient in</p><ul><li>3ds Max</li><li>Corona Renderer</li><li>Photoshop</li><li>AutoCAD</li><li>SketchUp</li></ul><p class="about-skills-label about-skills-label2">AI tools</p><ul><li>Codex</li><li>Claude</li><li>ComfyUI</li></ul></div></div><figure class="about-founder-photo"><img src="assets/founder-20261121-v5.jpg" alt="Ming-Xuan Liu, founder of FORM³, holding a glowing glass cube" width="940" height="941" loading="lazy" decoding="async"></figure></div></section>')+'<section class="section"><div class="wrap values">'+values.map((v,i)=>'<article class="value">'+aboutValueIcon(i)+'<span class="index">0'+(i+1)+'</span><h3>'+v[0]+'</h3><p>'+v[1]+'</p></article>').join('')+'</div></section>'+contactBand()}

// FORM3-345: keep an enquiry in memory while changing language; never persist contact data.
function contactInitial345(params,topic){
 if(params.has('quote'))return params.get('quote');
 const hints={website:pick('我想洽詢品牌網站與互動網頁設計。\n網站目的：\n預計頁面：\n必要功能：','I would like to discuss website design.\nSite purpose:\nExpected pages:\nRequired features:'),interior:pick('我想洽詢室內效果圖製作。\n空間類型：\n需求張數：\n期望時程：','I would like to discuss interior renderings.\nSpace type:\nImage count:\nTarget date:'),bobo:pick('我想了解立方體報報 BOBO 的試用方式。','I would like to learn about trial access to BOBO.')};
 return Object.prototype.hasOwnProperty.call(hints,topic)?hints[topic]:'';
}
function captureEnquiry345(){
 const form=document.querySelector('#enquiryForm');if(!form)return null;
 const fields={};for(const key of ['name','reply','service','stage','schedule','details']){const el=form.elements.namedItem(key);if(el)fields[key]={value:el.value,index:el.selectedIndex};}
 const active=document.activeElement,focus=active&&(form.contains(active)||active.id==='languageToggle')?{id:active.id,start:active.selectionStart,end:active.selectionEnd}:null;
 return {fields,focus,draft:document.querySelector('#draftText').value,href:document.querySelector('#mailDraft').getAttribute('href'),status:document.querySelector('#draftStatus').textContent,hidden:document.querySelector('#draftResult').hidden};
}
function restoreEnquiry345(state){
 const form=document.querySelector('#enquiryForm');if(!form||!state)return;
 for(const [key,saved]of Object.entries(state.fields)){const el=form.elements.namedItem(key);if(!el)continue;if(key==='stage'||key==='schedule')el.selectedIndex=saved.index;else el.value=saved.value;}
 document.querySelector('#draftText').value=state.draft;document.querySelector('#draftResult').hidden=state.hidden;document.querySelector('#draftStatus').textContent=state.status;
 const mail=document.querySelector('#mailDraft');if(state.href!==null)mail.setAttribute('href',state.href);
 const target=state.focus&&document.getElementById(state.focus.id);if(target){target.focus({preventScroll:true});if(typeof state.focus.start==='number'&&target.setSelectionRange)target.setSelectionRange(state.focus.start,state.focus.end);}
}

function contact(){const params=new URLSearchParams(location.hash.includes('?')?location.hash.split('?')[1]:location.search),topic=params.get('topic')||'';const opts=language==='zh'?[['automation','重複工作自動化／流程優化'],['software','客製軟體／工作工具'],['integration','資料與工具整合'],['ai','AI 輔助流程'],['website','網站與互動設計'],['interior','室內設計效果圖'],['music','數位音樂製作／MV 製作'],['unsure','還不確定，想先討論']]:[['automation','Workflow automation'],['software','Custom software / work tools'],['integration','Data & tool integration'],['ai','AI-assisted workflow'],['website','Website & interaction design'],['interior','Interior rendering'],['music','Digital music / music video'],['unsure','Not sure — let’s discuss']];const option=(v,t)=>'<option value="'+esc(v)+'"'+(topic===v?' selected':'')+'>'+esc(t)+'</option>';return intro('CONTACT',pick('聯絡我們','Contact us'),pick('先選擇需要的服務，補充聯絡方式，即可開始討論。','Choose a service and leave your contact details to begin.'),true)+'<section class="wrap contact-layout"><div class="contact-wave" aria-hidden="true">'+cropArt('wave')+'</div><aside class="contact-side"><h2>'+pick('一起把需求說清楚。','Let’s clarify your needs.')+'</h2><a class="mail" href="mailto:evilmike11111@gmail.com">evilmike11111@gmail.com ↗</a><p>'+pick('想先快速詢問，可使用右下角 LINE／Instagram 聯絡窗口。較完整的需求也能在這裡整理成郵件草稿。','For a quick question, use the LINE / Instagram contact window. This form helps you prepare a more detailed email enquiry.')+'</p>'+(language==='en'?'<p class="communication-note">I’m a Chinese creator and primarily communicate in Chinese. My English is limited, so English conversations are mainly handled through translation tools. Written messages are preferred.</p>':'')+'<p>'+pick(CONTENT.contact.dataNotice,'Please use anonymized examples. Do not include passwords, API keys or unauthorized personal data.')+'</p><a class="text-link" href="'+routes.process+'">'+pick('先了解合作流程','See how we work')+'</a></aside><form class="contact-form" id="enquiryForm"><div class="form-row"><label for="service">'+pick('想詢問的服務','Service')+' <span class="required-mark" aria-hidden="true">*</span></label><select id="service" name="service" required><option value="" disabled'+(!opts.some(x=>x[0]===topic)?' selected':'')+'>'+pick('請選擇服務','Select a service')+'</option>'+opts.map(x=>option(...x)).join('')+'</select></div><div class="form-two"><div class="form-row"><label for="name">'+pick('稱呼','Your name')+' <span class="required-mark" aria-hidden="true">*</span></label><input id="name" name="name" required maxlength="100" autocomplete="name"></div><div class="form-row"><label for="reply">'+pick('Email／LINE ID／IG 帳號','Email / LINE ID / Instagram')+' <span class="required-mark" aria-hidden="true">*</span></label><input id="reply" name="reply" required maxlength="200" autocomplete="off"></div></div><div class="form-row"><label for="stage">'+pick('目前進度','Project stage')+'</label><select id="stage" name="stage">'+pick(['先了解服務','已有想法，想討論可行性','已有資料，準備開始','希望改善現有成果'],['Exploring services','Have an idea — check feasibility','Materials ready — ready to start','Improve an existing project']).map(t=>'<option>'+esc(t)+'</option>').join('')+'</select></div><div class="form-row"><label for="schedule">'+pick('希望開始的時間','When would you like to start?')+'</label><select id="schedule" name="schedule">'+pick(['還不確定','越快越好，先討論安排','一個月內','一至三個月','三個月以後'],['Not sure yet','As soon as possible — discuss availability','Within a month','In 1–3 months','Later than 3 months']).map(t=>'<option>'+esc(t)+'</option>').join('')+'</select></div><div class="form-row"><label for="details">'+pick('補充一句需求（選填）','A short note (optional)')+'</label><textarea id="details" name="details" maxlength="1500" rows="3" placeholder="'+pick('例如：想把每週報表自動整理，或需要住宅客廳效果圖。','For example: automate weekly reports, or render a living room.')+'">'+esc(contactInitial345(params,topic))+'</textarea></div><p class="form-note">'+pick('按下送出後會直接寄到 FORM³ 信箱，我們會用你留下的聯絡方式回覆。','Your enquiry is sent straight to FORM³; we will reply using the contact details you leave.')+'</p><button class="button" type="submit">'+pick('送出洽詢','Send enquiry')+' ↗</button><p class="send-status" id="sendStatus" role="status" hidden></p><section class="draft-result" id="draftResult" hidden aria-live="polite"><h3>'+pick('洽詢草稿','Your enquiry draft')+'</h3><textarea id="draftText" readonly aria-label="'+pick('可複製的洽詢內容','Copyable enquiry draft')+'"></textarea><div class="actions"><a class="button" id="mailDraft">'+pick('開啟郵件程式','Open email app')+' ↗</a><button type="button" class="button ghost" id="copyDraft">'+pick('複製內容','Copy draft')+'</button></div><p class="caption" id="draftStatus"></p></section></form>'+contactSignal118()+'</section>'}

function boboTour(){const rows=[
['01 / QUOTE','assets/bobo-shot-quote-v1.webp',pick('一頁完成報價單','A complete quotation on one page'),pick('依工程大項排好工項，填數量與單價就自動算出小計與總價；可分版本、標狀態，直接匯出 PDF、Excel、CSV 或報價圖片。','Group work items under trade sections, enter quantities and unit prices, and subtotals and totals follow. Keep versions and status, then export to PDF, Excel, CSV or an image.')],
['02 / TEMPLATE','assets/bobo-shot-template-v1.webp',pick('估價範本，一鍵套用','Estimate templates, applied in one step'),pick('把常做的案型存成範本，例如「住宅 30 坪全室裝修」；套用到新報價後再依現場調整，不用每次從零開始。','Save common job types as templates, such as a full 30-ping home renovation, apply one to a new quotation and adjust it to the site instead of starting from zero.')],
['03 / WORK ITEMS','assets/bobo-shot-items-v1.webp',pick('工項庫：常用工項與單價集中管理','Work-item library with your usual prices'),pick('常用工項、規格說明、單位與客戶單價放在同一處，依天花、地面、牆壁等分類篩選，也能直接搜尋。','Keep your usual work items, specifications, units and client prices in one place, filtered by category or found by search.')],
['04 / MATERIALS','assets/bobo-shot-materials-v1.webp',pick('材料與成本，算得清楚','Materials and costs, kept clear'),pick('材料、分類與單價一起管理；每個工項都能接上材料與工資配方，報價時看得到成本。','Manage materials, categories and prices together; each work item can carry its material and labour recipe, so costs stay visible while quoting.')],
['05 / ASK','assets/bobo-shot-ai-v1.webp',pick('一句話查資料','Ask in a sentence'),pick('在工作台輸入「平釘天花多少錢」，直接找出工項、預設價與價格歷史；在本機查詢，資料不離開你的電腦。','Type a question such as the price of a flat ceiling and it finds the work item, default price and price history, searched locally on your computer.')]];
return '<section class="wrap bobo-tour" id="features"><p class="eyebrow">'+pick('實際程式畫面','ACTUAL SOFTWARE')+'</p><h2>'+pick('打開就能用的報價工具。','A quotation tool that works from day one.')+'</h2><p class="bobo-tour-lead">'+pick('第一次開啟可載入新手起手包：40 個住宅工項、69 種材料和一份 30 坪估價範本，馬上有資料可以練習。','On first launch you can load a starter pack: 40 residential work items, 69 materials and a 30-ping estimate template to practise with straight away.')+'</p>'+rows.map((r,i)=>'<article class="bobo-tour-row'+(i%2?' is-flip':'')+'"><div class="bobo-tour-copy"><p class="eyebrow">'+r[0]+'</p><h3>'+r[2]+'</h3><p>'+r[3]+'</p></div><figure class="bobo-tour-shot"><a href="'+r[1]+'" target="_blank" rel="noopener"><img src="'+r[1]+'" alt="'+r[2]+'" loading="lazy" decoding="async"></a><figcaption>'+pick('實際程式畫面 · 示範資料 · 點圖放大','Application interface · demo data · select to enlarge')+'</figcaption></figure></article>').join('')+'</section>'}
function boboDetail(){const features=language==='zh'?[['報價工作台','以報價單與工項資料，整理專案需要的資訊。'],['工項與材料','讓常用項目、材料與價格資料更容易查找。'],['歷史資料查詢','從既有資料尋找可參考的工項與報價記錄。'],['資料匯入流程','以實際檔案格式確認資料整理與匯入方式。']]:[['Quotation workspace','Organize the information needed for a project around quotations and work items.'],['Work items & materials','Make frequently used items, materials and pricing data easier to find.'],['Historical reference','Find relevant work items and quotation records in existing data.'],['Import workflow','Confirm data organization and import steps against actual file formats.']];return '<section class="wrap product-hero"><div><p class="eyebrow">BOBO / TOOLS BY FORM³</p><span class="status dev">'+pick('開發中 · 尚未開放下載','In development · Not yet available')+'</span><h2 class="product-title" style="margin-top:25px">'+pick('立方體報報','BOBO')+'</h2><h3>'+pick('讓報價資料，有清楚的工作位置。','A clearer workspace<br>for quotation data.')+'</h3><p>'+pick('結合報價、工項、材料與歷史資料查詢的工作工具。先把資料整理清楚，再讓常用的工作流程更容易執行。','A work tool bringing quotations, work items, materials and historical reference into one place. Organize the data first, then make everyday steps easier to follow.')+'</p><div class="actions"><a class="button" href="contact.html?topic=software">'+pick('詢問使用方式','Ask about getting started')+' ↗</a><a class="button ghost" href="#features">'+pick('了解功能方向','Explore the tool')+' ↓</a></div></div><figure class="product-artwork">'+productCover()+'</figure></section>'+boboTour()+'<section class="section"><div class="wrap">'+sectionHead('WORKFLOW',pick('資料先到位，工具才有用。','Useful tools start with usable data.'))+'<div class="product-steps">'+[pick('整理資料來源','Organize sources'),pick('建立工項脈絡','Structure work items'),pick('查詢與組成報價','Find & compose'),pick('覆核與交付','Review & deliver')].map((v,i)=>'<span>'+v+'</span>'+(i<3?'<i>→</i>':'')).join('')+'</div><p class="caption">'+pick('以上為產品方向說明，不承諾特定版本已具備所有功能。','This describes the product direction; not all functions are claimed for any particular version.')+'</p></div></section>'+contactBand()}

const TOOLBOX_RELEASE={version:'0.14.0',downloadUrl:"https://static.wixstatic.com/archives/1e153a_f57f5b7c49b540dbbdd6ba41ba10eb66.zip",size:69642858,notesZh:['試聽準備與播放狀態即時顯示，重播更順暢。','修正設定頁儲存按鈕遮擋與標題控制鈕外觀。','程式內可驗證、套用更新並自動重新開啟。'],notesEn:['Immediate preparation and playback feedback, with faster replay.','Clear save buttons and refined window controls.','Verified in-app updates with automatic restart.']};
