function bindProcess95(){
window.__form3ProcessCleanup?.();window.__form3ProcessCleanup=null;
const nav=document.querySelector('.process-overview');if(!nav)return;
const links=[...nav.querySelectorAll('a')],steps=[...document.querySelectorAll('.journey-step')],controller=new AbortController();
let active=-2,frame=0,holdUntil=0,settleTimer=0;
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function sensingLine(){const header=document.querySelector('.topbar')?.getBoundingClientRect().height||0;return Math.min(innerHeight*.48,Math.max(header+40,innerHeight*.35));}
function anchor(step){const r=step.getBoundingClientRect();return r.top+Math.min(r.height/2,140);}
function paint(i){if(i===active)return;active=i;links.forEach((a,j)=>{a.classList.toggle('is-passed',j<i);a.setAttribute('aria-current',j===i?'step':'false');a.tabIndex=(i<0||j===i)?0:-1});steps.forEach((s,j)=>s.classList.toggle('selected-stage',j===i));nav.style.setProperty('--stage-progress',(i<0?0:i/3*100)+'%');nav.style.setProperty('--stage-progress-n',i<0?0:i/3);}
function sync(){frame=0;if(performance.now()<holdUntil)return;const line=sensingLine();let k=-1;for(let j=0;j<steps.length;j++){if(steps[j].getBoundingClientRect().top<=line)k=j}paint(k)}
function queue(){if(!frame)frame=requestAnimationFrame(sync);}
function release(){holdUntil=0;clearTimeout(settleTimer);queue();}
function select(i,scroll){paint(i);if(!scroll)return;holdUntil=performance.now()+1100;clearTimeout(settleTimer);settleTimer=setTimeout(release,1120);const target=scrollY+anchor(steps[i])-sensingLine();window.scrollTo({top:Math.max(0,target),behavior:reduced()?'auto':'smooth'});}
links.forEach((a,i)=>{a.onclick=e=>{e.preventDefault();select(i,true)};a.onkeydown=e=>{let j=i;if(e.key==='ArrowRight'||e.key==='ArrowDown')j=(i+1)%links.length;else if(e.key==='ArrowLeft'||e.key==='ArrowUp')j=(i+links.length-1)%links.length;else if(e.key==='Home')j=0;else if(e.key==='End')j=links.length-1;else if(e.key===' '){e.preventDefault();select(i,true);return}else return;e.preventDefault();select(j,true);links[j].focus({preventScroll:true})}});
window.addEventListener('scroll',queue,{passive:true,signal:controller.signal});window.addEventListener('resize',release,{passive:true,signal:controller.signal});window.addEventListener('scrollend',()=>{if(performance.now()>=holdUntil-1000)release()},{passive:true,signal:controller.signal});window.addEventListener('wheel',release,{passive:true,signal:controller.signal});window.addEventListener('touchstart',release,{passive:true,signal:controller.signal});
window.__form3ProcessCleanup=()=>{controller.abort();cancelAnimationFrame(frame);clearTimeout(settleTimer);links.forEach(a=>{a.onclick=null;a.onkeydown=null})};
paint(-1);queue();
}

