 if(boxes.length){const left=Math.min(...boxes.map(b=>b.left)),right=Math.max(...boxes.map(b=>b.right));mark.style.left=(left-origin.left-4)+'px';mark.style.width=(right-left+8)+'px';mark.style.right='auto';const top=Math.min(...boxes.map(b=>b.top)),bottom=Math.max(...boxes.map(b=>b.bottom));mark.style.top=(top-origin.top-4)+'px';mark.style.height=(bottom-top+8)+'px';mark.style.bottom='auto'}
